from django.db import migrations, models

from prepgia import gia_languages
from prepgia.word_banks import de as german_bank, es as spanish_bank

GIA_LANGUAGE_LABELS = ["English", "Deutsch (Beta)", "Español (Beta)"]


def seed_german_and_spanish(apps, schema_editor):
    alias = schema_editor.connection.alias
    WordMeaningItem = apps.get_model("assessments", "WordMeaningItem")
    AssessmentTrack = apps.get_model("assessments", "AssessmentTrack")
    items = WordMeaningItem.objects.using(alias)
    for language, bank in (("de", german_bank), ("es", spanish_bank)):
        suffix = gia_languages.WORD_MEANING_ODD_SUFFIX[language]
        for first, second, difficulty, relationship, explanation, odd_words in bank.WORD_CONCEPTS:
            for odd in odd_words:
                items.get_or_create(
                    language=language, pair_word_1=first, pair_word_2=second, odd_word=odd, difficulty=difficulty,
                    defaults={
                        "relationship_type": relationship,
                        "explanation": explanation + suffix.format(odd=odd),
                        "tags": ["original", "beta", f"lang-{language}", "2026-11"],
                    },
                )
    # Thomas GIA tracks now list the new languages instead of "coming soon".
    for track in AssessmentTrack.objects.using(alias).filter(assessment_type="prepgia"):
        languages = [lang for lang in (track.available_languages or []) if "coming soon" not in lang.lower()]
        for label in GIA_LANGUAGE_LABELS:
            if label not in languages:
                languages.append(label)
        track.available_languages = languages
        track.save(update_fields=["available_languages"])



